export const BODY: string = "\n<p>الصور هي الجزء الأثقل في معظم المواقع الإلكترونية. صفحة تحمل بسرعة قد تتباطأ بسبب صورة واحدة بوزن 5 ميغابايت.</p>\n<p>يمر هذا الدليل بعملية التحسين كاملة. ستفحص الصفحة، وتختار الإعداد الصحيح، وترفع الصور، وتنسخ وسوم HTML الجاهزة.</p>\n<p>يعمل ذلك للمدونات والمتاجر ومواقع الأعمال، دون حاجة إلى خبرة برمجية.</p>\n<h2 id=\"audit-first\">الخطوة 1: افحص الصفحة أولًا</h2>\n<p>الخطوة 1: افحص الصفحة أولًا. استخدم أداة قياس سرعة مجانية لمعرفة أي الصور تثقل الصفحة، وكم يبلغ وزنها الإجمالي.</p>\n<p>الفحص يخبرك أين تتركز المشكلة: صورة رئيسية ضخمة أم عشرات الصور الصغيرة. ركّز جهدك على أكبر الصور أولًا.</p>\n<h2 id=\"step-2-open\">الخطوة 2: افتح محسّن صور الويب</h2>\n<p>افتح <a href=\"/ar/tahsin-suwar-al-web/\">محسّن صور الويب</a> في متصفحك. تعمل الأداة بالكامل على جهازك دون رفع الصور إلى أي خادم.</p>\n<p>لا حاجة إلى حساب أو تثبيت. افتح الصفحة وابدأ فورًا، وستبقى صورك خاصة طوال العملية.</p>\n<h2 id=\"step-3-preset\">الخطوة 3: اختر الإعداد الصحيح</h2>\n<p>اختر الإعداد الصحيح حسب موضع الصورة: رئيسية للصور الكبيرة، ومنتج لصور المتجر، وبطاقة للصور الصغيرة.</p>\n<p>الإعداد الصحيح يحدد الأبعاد والجودة والصيغة المناسبة لذلك الموضع. الاختيار الصحيح يختصر التخمين.</p>\n<h2 id=\"step-4-upload\">الخطوة 4: ارفع الصور</h2>\n<p>ارفع الصور التي تريد تحسينها. تُقبل ملفات JPG وPNG وWebP وHEIC، بحجم إدخال يصل إلى 25 ميغابايت لكل ملف.</p>\n<p>إذا رفعت عدة صور، فستظهر كل واحدة في قائمة. يمكنك ضبط الإعدادات لكل صورة أو تطبيق الإعداد نفسه على الكل.</p>\n<h2 id=\"step-5-customise\">الخطوة 5: خصّص الإعدادات</h2>\n<p>خصّص الإعدادات إذا احتجت: غيّر الجودة أو الأبعاد أو الصيغة حسب متطلبات موقعك. الإعدادات الافتراضية تناسب معظم الحالات.</p>\n<p>للصور الرئيسية، ارفع الجودة قليلًا. وللصور المصغرة، اخفض الأبعاد لتوفير مزيد من الحجم.</p>\n<h2 id=\"step-6-preview\">الخطوة 6: راجع النتائج</h2>\n<p>راجع النتائج قبل التنزيل. قارن كل صورة بالأصل، وتأكد من أن التفاصيل المهمة واضحة وأن الألوان صحيحة.</p>\n<p>إذا بدت نتيجة ما ناعمة أكثر من اللازم، فأعد تحسين تلك الصورة بإعدادات مختلفة. لا تقبل نتيجة سيئة أملًا في أن لا يلاحظها أحد.</p>\n<h2 id=\"step-7-copy-html\">الخطوة 7: انسخ وسم HTML</h2>\n<p>انسخ وسم HTML الجاهز لكل صورة. الوسم يحمل الأبعاد الصحيحة والنص البديل وسمات التحميل الكسول.</p>\n<p>الصق الوسم في صفحتك بدل كتابته يدويًا. النسخ يمنع أخطاء الكتابة ويوفر الوقت.</p>\n<h2 id=\"step-8-upload\">الخطوة 8: ارفع واختبر الصفحة</h2>\n<p>ارفع الصور المحسّنة إلى موقعك واختبر الصفحة. استخدم أداة قياس السرعة نفسها لمقارنة النتيجة قبل التحسين وبعده.</p>\n<p>إذا تحسنت الأرقام وبدت الصور جيدة، فقد نجحت. إذا لم تتحسن، فافحص الصور التي لم تحسّنها بعد.</p>\n<h2 id=\"fixing-problems\">كيف تحل المشاكل الشائعة؟</h2>\n<p>إذا ظهرت مشكلة شائعة، فافحص السبب أولًا. الصورة التي لم تتحسن سرعتها غالبًا لم تُحسّن أصلًا أو رُفعت بنسختها القديمة.</p>\n<p>تحقق من أنك رفعت الملف المحسّن لا الأصل. الخلط بين الملفين هو أكثر الأخطاء شيوعًا بعد التحسين.</p>\n<h2 id=\"blog-workflow\">سير العمل: مقالة مدونة</h2>\n<p>لمقالة مدونة، حسّن الصورة المميزة بإعداد الصورة الرئيسية، والصور داخل المقال بإعداد البطاقة. كل موضع يحصل على إعداداته.</p>\n<p>اكتب نصًا بديلًا لكل صورة يصف محتواها. النص البديل يساعد محركات البحث وقارئات الشاشة على فهم الصورة.</p>\n<h2 id=\"shop-workflow\">سير العمل: صفحة منتج</h2>\n<p>لصفحة منتج، حسّن الصورة الرئيسية بإعداد المنتج بأبعاد مربعة وجودة عالية. المشتري يحتاج إلى رؤية تفاصيل المنتج بوضوح.</p>\n<p>للصور الإضافية للمنتج، استخدم إعدادًا أخف. الصور الإضافية تظهر صغيرة، فلا حاجة إلى ملفات كبيرة لها.</p>\n<h2 id=\"speed-tools\">كيف تستخدم أدوات السرعة المجانية جيدًا؟</h2>\n<p>أدوات السرعة المجانية مثل PageSpeed Insights تقيس موقعك وتعطيك تقريرًا مفصلًا. استخدمها قبل التحسين وبعده لمقارنة النتائج.</p>\n<p>ركّز على مؤشرات الصور في التقرير: أكبر رسم محتوى وسرعة التحميل. هذه المؤشرات تتحسن مباشرة بعد تحسين الصور.</p>\n<h2 id=\"image-sizes-by-slot\">كيف تختار الأحجام حسب موضع الصفحة؟</h2>\n<p>اختر الأحجام حسب موضع الصورة في الصفحة: رئيسية كبيرة، وبطاقة صغيرة، ومصغرة أصغر. كل موضع له حجمه المناسب.</p>\n<p>لا ترفع صورة 2000 بكسل لعرضها بحجم 300 بكسل. الأبعاد الزائدة تهدر حجمًا دون فائدة مرئية.</p>\n<h2 id=\"srcset-basics\">الصور المتجاوبة عمليًا</h2>\n<p>الصور المتجاوبة تعني تقديم أحجام مختلفة لأجهزة مختلفة. الهاتف يحصل على صورة أصغر، والحاسوب يحصل على صورة أكبر.</p>\n<p>استخدم سمة srcset في وسم الصورة. المتصفح يختار الحجم المناسب لشاشة الزائر تلقائيًا، فيوفر البيانات على الجوال.</p>\n<h2 id=\"image-seo\">تحسين محركات البحث للصور أثناء التحسين</h2>\n<p>تحسين محركات البحث للصور أثناء التحسين يبدأ من اسم الملف والنص البديل. سمِّ ملفك بكلمات تصف المحتوى، واكتب نصًا بديلًا واضحًا.</p>\n<p>حجم الملف الصغير يساعد أيضًا في سرعة الصفحة، وسرعة الصفحة عامل ترتيب مهم. الصور السريعة ترفع ترتيب موقعك.</p>\n<h2 id=\"maintenance\">كيف تحافظ على صورك محسّنة مع الوقت؟</h2>\n<p>للحفاظ على الصور محسّنة مع الوقت، اجعل التحسين جزءًا من سير عمل النشر. كل صورة جديدة تمر عبر الأداة قبل الرفع.</p>\n<p>راجع صور موقعك كل بضعة أشهر. الصور القديمة غير المحسّنة قد تكون ما زالت تثقل صفحات مهمة.</p>\n<h2 id=\"team-optimisation\">معايير تحسين للفرق</h2>\n<p>لمعايير تحسين للفرق، حدد إعدادات موحدة: صيغة JPG وهدف حجم لكل نوع صورة وأبعاد ثابتة. التوحيد يمنع اختلاف النتائج بين أعضاء الفريق.</p>\n<p>شارك قالبًا لسير العمل مع الفريق. القالب الواضح يعني أن أي شخص يستطيع تحسين صورة دون أخطاء.</p>\n<h2 id=\"common-speed-myths\">خرافات سرعة يجدر تجاهلها</h2>\n<p>من خرافات السرعة الشائعة أن الصور الصغيرة لا تهم. الحقيقة أن عشر صور صغيرة غير محسّنة قد تثقل الصفحة أكثر من صورة كبيرة واحدة.</p>\n<p>وخرافة أخرى أن الضغط يفسد الجودة دائمًا. الضغط الذكي إلى حجم مناسب يحافظ على جودة ممتازة على الشاشة.</p>\n<h2 id=\"final-check-speed\">مراجعة أخيرة قبل النشر</h2>\n<p>قبل النشر، راجع كل صورة: الجودة والأبعاد والاسم والنص البديل. الفحص الأخير يمنع الأخطاء البسيطة التي تكلفك لاحقًا.</p>\n<p>اختبر الصفحة على الهاتف والحاسوب. الصفحة السريعة على الجهازين تعني أن التحسين نجح فعلًا.</p>\n<h2 id=\"keep-learning\">تابع التعلم من كل صفحة</h2>\n<p>تعلّم من كل صفحة تحسّنها. سجّل ما عمل وما لم يعمل، واستخدم الدروس في الصفحة التالية.</p>\n<p>التحسين مهارة تتحسن بالممارسة. وللتعمق، اقرأ <a href=\"/ar/blog/dalil-tahsin-suwar-al-web/\">الدليل الكامل لمحسّن صور الويب</a> و<a href=\"/ar/blog/tahsin-as-suwar-li-core-web-vitals/\">تحسين الصور لمؤشرات الويب الأساسية</a>، أو جرّب <a href=\"/ar/daght-as-sura-ila-200kb/\">ضاغط 200 كيلوبايت</a> للصور الرئيسية.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"كم سيصبح موقعي أسرع بعد تحسين الصور؟","answer":"يعتمد على صورك الحالية، لكن معظم المواقع تصبح أسرع بنسبة 30 إلى 50 بالمئة بعد تحسين الصور. الصفحات التي كانت تحمل صورًا بوزن ميغابايتات تشهد أكبر تحسن."},{"question":"هل أحسّن الصور قبل رفعها إلى موقعي أم بعد؟","answer":"حسّن الصور قبل رفعها إلى موقعك. بهذا ترفع النسخ المحسّنة فقط، ولا تتراكم النسخ الثقيلة في مكتبة الوسائط لديك."},{"question":"هل يمكنني تحسين ثلاثين صورة مدونة في دفعة واحدة؟","answer":"نعم، بأداة التحسين بالجملة. ارفع ثلاثين صورة دفعة واحدة وحدد الإعداد المناسب لكل نوع، ثم نزّل النتائج كملف ZIP."},{"question":"لماذا ما زالت صورتي الرئيسية بطيئة بعد تحسينها؟","answer":"لأن الصورة الرئيسية يجب أن تحمل فورًا دون تحميل كسول، وأن أبعادها قد تكون أكبر من اللازم. تحقق من إعداد الصورة الرئيسية ومن حجم الملف."},{"question":"هل أحتاج إلى تحديث HTML عندما أستبدل صورة؟","answer":"نعم، إذا غيّرت اسم الملف أو مساره. حدّث وسم الصورة في صفحتك ليشير إلى الملف الجديد، أو احتفظ بالاسم نفسه عند الاستبدال."},{"question":"ما حجم الصورة الذي أستخدمه لصورة مدونة مميزة؟","answer":"لصورة مدونة مميزة، استخدم 1200 في 630 بكسل. هذه الأبعاد تناسب معظم قوالب المدونات وتظهر جيدًا في المشاركة الاجتماعية أيضًا."}];
